def excedances {n : ℕ} (π : Perm (Fin n)) : Finset (Fin n) := Finset.univ.filter (fun i => π i > i)
def eulerianNumber (n k : ℕ) : ℕ := Fintype.card {π : Perm (Fin n) | (excedances π).card = k}
def coexcedances {n : ℕ} (π : Perm (Fin n)) : Finset (Fin n) := Finset.univ.filter (fun i => π i < i)

